/**
 * Global climate context for the Earth globe and Ask Earth.
 *
 * Observed years come straight from the agencies' files, regenerated by
 * `node scripts/build-global-record.mts` into lib/global-record.json:
 *   • NASA GISTEMP v4 zonal annual means — °C anomaly relative to the 1951–1980 mean
 *     https://data.giss.nasa.gov/gistemp/tabledata_v4/ZonAnn.Ts+dSST.csv
 *   • NSIDC Sea Ice Index v4 — Arctic September (annual minimum) extent, million km²
 *     https://noaadata.apps.nsidc.org/NOAA/G02135/north/monthly/data/N_09_extent_v4.0.csv
 *   • NOAA GML — Mauna Loa annual mean CO2, ppm
 *     https://gml.noaa.gov/webdata/ccgg/trends/co2/co2_annmean_mlo.txt
 *
 * Years after the last observation are NOT model output: each variable is extended along the
 * linear trend of its last 30 observed years and flagged `projected: true`. For real scenario
 * context we quote the IPCC AR6 assessment (see AR6_SSP245).
 */
import record from "./global-record.json";
import { linearTrend } from "./stats";

export interface NasaGlobalRecord {
  year: number;
  globalTempAnomaly: number; // °C vs 1951–1980
  arcticTempAnomaly: number; // 64°N–90°N
  northMidTempAnomaly: number; // 44°N–64°N
  northSubTempAnomaly: number; // 24°N–44°N
  equTo24NTempAnomaly: number; // 0°–24°N
  equTo24STempAnomaly: number; // 24°S–0°
  southSubTempAnomaly: number; // 44°S–24°S
  southMidTempAnomaly: number; // 64°S–44°S
  antarcticTempAnomaly: number; // 90°S–64°S
  seaIceExtent: number; // Arctic September extent, million km²
  co2Ppm: number;
  projected: boolean;
  source: string;
}

type Values = Omit<NasaGlobalRecord, "year" | "projected" | "source">;
const FIELDS = ["globalTempAnomaly", "arcticTempAnomaly", "northMidTempAnomaly", "northSubTempAnomaly", "equTo24NTempAnomaly", "equTo24STempAnomaly", "southSubTempAnomaly", "southMidTempAnomaly", "antarcticTempAnomaly", "seaIceExtent", "co2Ppm"] as const satisfies readonly (keyof Values)[];

export const GLOBAL_FIRST: number = record.first;
export const GLOBAL_LAST: number = record.last;
export const PROJECTION_END = 2050;
/** Window whose linear trend is extended beyond the last observation. */
export const TREND_WINDOW: [number, number] = [GLOBAL_LAST - 29, GLOBAL_LAST];

const OBSERVED_SOURCE = "NASA GISTEMP v4 · NSIDC Sea Ice Index v4 · NOAA GML";
const PROJECTED_SOURCE = `Trend extrapolation of ${TREND_WINDOW[0]}–${TREND_WINDOW[1]} observations — illustrative, not a climate model`;

const observed = new Map<number, NasaGlobalRecord>(
  Object.entries(record.years as Record<string, Values>).map(([y, v]) => [Number(y), { year: Number(y), ...v, projected: false, source: OBSERVED_SOURCE }]),
);

const trends = Object.fromEntries(FIELDS.map(f => {
  const years = [...observed.keys()].filter(y => y >= TREND_WINDOW[0] && y <= TREND_WINDOW[1]);
  const t = linearTrend(years, years.map(y => observed.get(y)![f]));
  return [f, t];
})) as Record<(typeof FIELDS)[number], ReturnType<typeof linearTrend>>;

/** IPCC AR6 WGI SPM Table SPM.1, SSP2-4.5: best estimate (very likely range), °C vs 1850–1900. */
export const AR6_SSP245 = {
  near: { period: "2021–2040", best: 1.5, range: [1.2, 1.8] },
  mid: { period: "2041–2060", best: 2.0, range: [1.6, 2.5] },
  long: { period: "2081–2100", best: 2.7, range: [2.1, 3.5] },
  source: "IPCC AR6 WGI Summary for Policymakers, Table SPM.1 (2021)",
} as const;

export const PROJECTION_NOTE = `Values after ${GLOBAL_LAST} extend the ${TREND_WINDOW[0]}–${TREND_WINDOW[1]} linear trend of the observations; they are an illustration, not a climate-model projection. For comparison, IPCC AR6 assesses SSP2-4.5 global warming of ${AR6_SSP245.near.best.toFixed(1)} °C (${AR6_SSP245.near.range.map(v => v.toFixed(1)).join("–")} °C) for ${AR6_SSP245.near.period} and ${AR6_SSP245.mid.best.toFixed(1)} °C (${AR6_SSP245.mid.range.map(v => v.toFixed(1)).join("–")} °C) for ${AR6_SSP245.mid.period}, relative to 1850–1900.`;

/** First observed Arctic September sea-ice extent, used as the "since" reference. */
export const SEA_ICE_REFERENCE = { year: GLOBAL_FIRST, extent: observed.get(GLOBAL_FIRST)!.seaIceExtent };
export const CO2_REFERENCE = { year: GLOBAL_FIRST, ppm: observed.get(GLOBAL_FIRST)!.co2Ppm };

/** Observed rate of change of any variable over the full record (per decade, with 95 % CI). */
export function observedRate(field: (typeof FIELDS)[number], from = GLOBAL_FIRST) {
  const years = [...observed.keys()].filter(y => y >= from);
  const t = linearTrend(years, years.map(y => observed.get(y)![field]))!;
  return { perDecade: t.slope * 10, ci95: [t.ci95[0] * 10, t.ci95[1] * 10] as [number, number], pValue: t.pValue, from, to: GLOBAL_LAST };
}

/** Observed global warming rate over the full record (°C per decade, with 95 % CI). */
export const globalWarmingRate = () => observedRate("globalTempAnomaly");

/** Observed values for GLOBAL_FIRST…GLOBAL_LAST, trend extrapolation (flagged) up to 2050. */
export function getNasaGlobalData(year: number): NasaGlobalRecord {
  const y = Math.round(Math.max(GLOBAL_FIRST, Math.min(PROJECTION_END, year)));
  const obs = observed.get(y);
  if (obs) return obs;
  const values = Object.fromEntries(FIELDS.map(f => {
    const t = trends[f]!;
    let v = t.intercept + t.slope * y;
    if (f === "seaIceExtent") v = Math.max(0, v);
    return [f, +v.toFixed(2)];
  })) as Values;
  return { year: y, ...values, projected: true, source: PROJECTED_SOURCE };
}
